export function renderBoard(puzzle, pegs, selected, targets) {
  const board = document.getElementById('board');
  board.innerHTML = '';

  const cells = puzzle.cells;
  const xs = cells.map(c => parseInt(c.split(',')[0]));
  const ys = cells.map(c => parseInt(c.split(',')[1]));
  const minX = Math.min(...xs);
  const maxX = Math.max(...xs);
  const minY = Math.min(...ys);
  const maxY = Math.max(...ys);
  const cols = maxX - minX + 1;
  const rows = maxY - minY + 1;

  board.style.gridTemplateColumns = `repeat(${cols}, 1fr)`;
  board.style.gridTemplateRows = `repeat(${rows}, 1fr)`;

  const pegSet = new Set(pegs);
  const goalSet = new Set(puzzle.goal);
  const targetSet = new Set(targets);

  for (let y = minY; y <= maxY; y++) {
    for (let x = minX; x <= maxX; x++) {
      const cellId = `${x},${y}`;
      const isOccupied = pegSet.has(cellId);
      const isGoal = goalSet.has(cellId);
      const isSelected = selected === cellId;
      const isTarget = targetSet.has(cellId);

      const btn = document.createElement('button');
      btn.dataset.cell = cellId;
      btn.dataset.occupied = isOccupied ? 'true' : 'false';
      btn.className = '';
      if (isOccupied) btn.classList.add('peg');
      if (isGoal) btn.classList.add('goal');
      if (isSelected) btn.classList.add('selected');
      if (isTarget) btn.classList.add('target');

      btn.setAttribute('aria-label', `${cellId}, ${isOccupied ? 'occupied' : 'empty'}`);
      if (isSelected) btn.setAttribute('aria-pressed', 'true');

      board.appendChild(btn);
    }
  }
}
